export async function dirtyGoverned(session: Session): Promise<string[]> {
  const changed = pathsOf(await session.git.changedSince(await session.git.head()));
  return changed.filter((path) => !path.startsWith(".specty/") && isGoverned(path, session.config));
}

import type { CardContext } from "./view";

/**
 * `specty next` with no change active: code changed without a spec goes to a retro, a new project
 * starts with its skeleton, and otherwise the agent creates the change the user asks for, or,
 * when its tool hands work to subagents, launches one per change with its brief.
 */
export function noChangeCard(dirty: readonly string[], ctx: CardContext, fresh: boolean): Output {
  if (dirty.length > 0) return withoutSpecCard(dirty, ctx);

/** A repository with one commit containing `files`. */
export async function tempRepo(files: Readonly<Record<string, string>>): Promise<string> {
  const root = await realpath(await mkdtemp(join(tmpdir(), "specty-")));
  git(root, "init", "-q", "-b", "main");
  git(root, "config", "user.name", "Ana");
  git(root, "config", "user.email", "ana@example.com");
  await writeFiles(root, files);
  git(root, "add", "-A");
  git(root, "commit", "-q", "-m", "init");
  return root;
}

